using System.Text.Json;
int n=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);n++;Console.WriteLine("PASS "+label);}
Guid session=Guid.NewGuid(),actor=Guid.NewGuid();ToolOutcomeSnapshot Snap(int count)=>new(session,actor,Guid.NewGuid(),JsonSerializer.SerializeToElement(new{slots=new[]{new{slot=0,value=count==0?0:89,count}}}));
var zero=Snap(0);var one=Snap(1);var two=Snap(2);var state=new ToolOutcomeFeedback();var unfinished=new[]{new ToolUnexecutedStep("act_PickUp","old reference unavailable")};string goal=new string('g',200)+" finally eat new food";
state.Unexecuted(goal,one,unfinished);Check(state.Value.GetProperty("status").GetString()=="no_valid_delta","first failed revalidation does not fabricate earlier action");Check(state.Value.GetProperty("originalGoal").GetString()==goal,"overall goal longer than160 preserved");
state.Begin(zero,"host_navigate_local",goal);state.Bind(17);Check(!state.Complete(17,"running",one),"running is not outcome");Check(state.Complete(17,"arrived",one),"actual navigation terminal accepted");Check(state.Value.GetProperty("inventoryDelta")[0].GetProperty("net").GetInt64()==1,"actual before snapshot survived in-flight observation");
string completed=state.Value.GetRawText();state.Begin(one,"act_PickUp",goal);state.Bind(18);Check(state.Value.GetRawText()==completed,"starting new action preserves latest completed outcome");Check(!state.Complete(99,"succeeded",two)&&state.Value.GetRawText()==completed,"wrong receipt cannot overwrite terminal outcome");Check(!state.Complete(18,"running",two)&&state.Value.GetRawText()==completed,"running successor cannot occupy main feedback");
Check(state.Complete(18,"failed",Snap(1)),"real failed terminal accepted");Check(state.Value.GetProperty("preceding").GetProperty("status").GetString()=="failed","failure not rewritten as success");state.Unexecuted(goal,two,unfinished);Check(state.Value.GetProperty("inventoryDelta")[0].GetProperty("net").GetInt64()==1,"fresh failed-step observation reflects concurrent inventory growth");Check(state.Value.GetProperty("unexecuted")[0].GetProperty("executed").GetBoolean()==false,"old step explicitly never executed");Check(state.Value.GetProperty("preceding").GetProperty("sequence").GetInt64()==18,"failed step feedback retains actual preceding receipt identity");
state.Begin(two,"act_Eat",goal);state.Bind(19);Check(state.Complete(19,"succeeded",one),"immediate successful tool completion supported");Check(state.Value.GetProperty("inventoryDelta")[0].GetProperty("net").GetInt64()==-1,"consumption negative inventory delta no source inference");
state.Begin(one,"act_Wait",goal);state.Bind(20);Check(state.Complete(20,"cancelled",Snap(1)),"cancelled terminal supported");Check(state.Value.GetProperty("inventoryDelta").GetArrayLength()==0,"unchanged inventory remains empty delta");
state.Begin(one,"act_PickUp",goal);state.Bind(21);Check(!state.Complete(21,"unexpected",two),"unknown terminal produces no invented delta");Check(state.Value.GetProperty("status").GetString()=="no_valid_delta","unknown terminal explicitly unavailable");
state.Begin(one,"act_Eat",goal);state.Bind(22);state.Complete(22,"succeeded",two with{ActorId=Guid.NewGuid()});Check(state.Value.GetProperty("reason").GetString()=="invalid_observation_or_terminal","cross actor terminal snapshot degrades to explicit invalid feedback");
state.Begin(one,"act_PickUp",goal);state.AbortDispatch("native_receipt_not_returned");Check(state.Value.GetProperty("reason").GetString()=="native_receipt_not_returned","nonreturned receipt never assigned terminal success");
state.UnknownDispatch(goal,"act_PickUp","exception_after_call_entered",new[]{new ToolUnexecutedStep("act_Eat","plan_abandoned")});
Check(state.Value.GetProperty("status").GetString()=="outcome_unknown"&&state.Value.GetProperty("executed").ValueKind==JsonValueKind.Null,"attempted call not mislabeled unexecuted");
Check(state.Value.GetProperty("unexecuted").GetArrayLength()==1&&state.Value.GetProperty("unexecuted")[0].GetProperty("tool").GetString()=="act_Eat","only truly unattempted remainder is unexecuted");
Check(!state.Value.GetProperty("replayAuthorized").GetBoolean(),"uncertain attempted call does not authorize replay");
Console.WriteLine("TOTAL "+n);
